#pragma once

#include "CoreMinimal.h"
#include "UObject/Object.h"
#include "ArenaScoreTracker.generated.h"

/**
 * Tracks per-team scores for an arena match.
 * Must be a UObject (UCLASS) so it can be created with NewObject and
 * garbage-collected with its outer; a plain C++ class here broke the
 * packaged build (NewObject returned null -> crash in AddPoints).
 */
UCLASS()
class PIXELARENA_API UArenaScoreTracker : public UObject
{
	GENERATED_BODY()

public:
	void AddPoints(int32 TeamIndex, int32 Points);
	int32 GetPoints(int32 TeamIndex) const;

private:
	UPROPERTY()
	TMap<int32, int32> PointsByTeam;
};

--- result.json ---
{
  "crash_cause": "Null pointer dereference in UArenaScoreTracker::AddPoints (ArenaScoreTracker.cpp:18), called from AArenaGameMode::OnGoalScored (ArenaGameMode.cpp:38) when a goal was scored. The ScoreTracker was created with NewObject<UArenaScoreTracker>(this) but the class was not a proper UObject (it lacked UCLASS()/GENERATED_BODY() and a UObject base), so the object was null/invalid in the packaged Shipping build and AddPoints dereferenced it (EXCEPTION_ACCESS_VIOLATION reading 0xffffffffffffffff). Fixed by making UArenaScoreTracker a real UCLASS UObject with GENERATED_BODY() and a UPROPERTY score map.",
  "no_colors_cause": "The arena palette asset /Game/Data/Palettes/DA_Primary was not cooked into the packaged build. Log lines 4-6 show 'Couldn't find file for package /Game/Data/Palettes/DA_Primary', 'Failed to find object ... DA_Primary.DA_Primary', and 'Palette is null, using fallback gray'. Config/DefaultGame.ini had bCookAll=False and only /Game/Data/Effects in DirectoriesToAlwaysCook, so the Palettes directory was excluded from cooking. Fixed by adding /Game/Data/Palettes to DirectoriesToAlwaysCook."
}
